INSERT INTO tests (code, title, description, created_by) VALUES ('spd_01', 'Методика СПД', 'Импортировано из docx', 1) ON CONFLICT (code) DO NOTHING;
INSERT INTO test_versions (test_id, version_no, instruction, is_published, created_by) SELECT id, 1, 'Инструкция. Тебе предлагается ряд вопросов, которые помогут определить некоторые свойства твоей личности. Здесь не может быть ответов «правильных» и «ошибочных». Мы ждем твой ответ, основанный на твоем мнении. Отвечая на каждый вопрос, выбери ответ, который в наибольшей степени соответствует твоему мнению о себе.', true, 1 FROM tests WHERE code = 'spd_01' ON CONFLICT (test_id, version_no) DO NOTHING;
INSERT INTO questions (version_id, order_num, code, text, question_type, is_required) SELECT id, 1, 'Q_1', 'Я всегда сдерживаю свои обещания.', 'scale', true FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'spd_01') AND version_no = 1 ON CONFLICT (version_id, code) DO NOTHING;
